public with sharing class WorkItemHoursCalculator {
    private final UOW uow;

    public WorkItemHoursCalculator(UOW uow) {
        this.uow = uow;
    }

    /**
     * Calculate and update actual hours for work items and all their ancestors
     * Actual Hours = Total Logged Hours (direct time entries) + Sum of all children's Actual Hours (recursive)
     */
    public void calculateActualHours(Set<Id> workItemIds) {
        if (workItemIds == null || workItemIds.isEmpty()) {
            return;
        }

        // Get all work items in the hierarchy, starting from the initial set and going up to the roots
        Map<Id, Work_Item__c> allWorkItems = getWorkItemHierarchy(workItemIds);

        // Get all direct children for each work item within the fetched hierarchy
        Map<Id, List<Work_Item__c>> childrenByParentId = groupChildrenByParent(allWorkItems.values());

        // Process from leaves up to roots to ensure children are calculated before parents
        List<Work_Item__c> sortedWorkItems = sortFromLeavesToRoots(allWorkItems, childrenByParentId);

        for (Work_Item__c workItem : sortedWorkItems) {
            // Start with direct logged hours
            Decimal newActualHours = workItem.Total_Logged_Hours__c ?? 0;

            // Add children's actual hours
            if (childrenByParentId.containsKey(workItem.Id)) {
                for (Work_Item__c child : childrenByParentId.get(workItem.Id)) {
                    // Use the already-calculated child hours from the map
                    Work_Item__c childFromMap = allWorkItems.get(child.Id);
                    if (childFromMap != null) {
                        newActualHours += childFromMap.Actual_Hours__c ?? 0;
                    }
                }
            }

            // If the hours have changed, update the record in memory and register with UOW
            if (workItem.Actual_Hours__c != newActualHours) {
                workItem.Actual_Hours__c = newActualHours;
                this.uow.registerDirty(workItem);
            }
        }
    }

    /**
     * Query all work items in the hierarchy, including parents and children
     */
    private Map<Id, Work_Item__c> getWorkItemHierarchy(Set<Id> initialIds) {
        Map<Id, Work_Item__c> allWorkItems = new Map<Id, Work_Item__c>();
        Set<Id> idsToQuery = new Set<Id>(initialIds);
        Set<Id> queriedIds = new Set<Id>();

        // Limit iterations to prevent infinite loops in case of data issues
        for (Integer i = 0; i < 10; i++) {
            if (idsToQuery.isEmpty()) {
                break;
            }

            Set<Id> currentBatch = new Set<Id>();
            for (Id id : idsToQuery) {
                if (!queriedIds.contains(id)) {
                    currentBatch.add(id);
                }
            }

            if (currentBatch.isEmpty()) {
                break;
            }

            List<Work_Item__c> workItems = [
                SELECT Id, Parent_Work_Item__c, Total_Logged_Hours__c, Actual_Hours__c
                FROM Work_Item__c
                WHERE Id IN :currentBatch
                WITH USER_MODE
            ];

            queriedIds.addAll(currentBatch);
            idsToQuery.clear();

            for (Work_Item__c wi : workItems) {
                if (!allWorkItems.containsKey(wi.Id)) {
                    allWorkItems.put(wi.Id, wi);
                    if (wi.Parent_Work_Item__c != null && !queriedIds.contains(wi.Parent_Work_Item__c)) {
                        idsToQuery.add(wi.Parent_Work_Item__c);
                    }
                }
            }
        }
        return allWorkItems;
    }

    /**
     * Group children by their parent ID
     */
    private Map<Id, List<Work_Item__c>> groupChildrenByParent(List<Work_Item__c> workItems) {
        Map<Id, List<Work_Item__c>> childrenByParentId = new Map<Id, List<Work_Item__c>>();
        for (Work_Item__c wi : workItems) {
            if (wi.Parent_Work_Item__c != null) {
                if (!childrenByParentId.containsKey(wi.Parent_Work_Item__c)) {
