public with sharing class WorkItemHoursCalculator {
    private final UOW uow = new UOW(new List<SObjectType>{ Work_Item__c.SObjectType });

    /**
     * Calculate and update actual hours for work items and all their ancestors
     * Actual Hours = Total Logged Hours (direct time entries) + Sum of all children's Actual Hours (recursive)
     */
    public void calculateActualHours(Set<Id> workItemIds) {
        if (workItemIds.isEmpty()) {
            return;
        }

        // Get work items with their logged hours and parent IDs
        List<Work_Item__c> workItemsQueried = [
            SELECT Total_Logged_Hours__c, Parent_Work_Item__c, Actual_Hours__c
            FROM Work_Item__c
            WHERE Id IN :workItemIds OR Parent_Work_Item__c IN :workItemIds
            WITH USER_MODE
        ];

        List<Work_Item__c> workItemsToProcess = new List<Work_Item__c>();

        // Get all children and their actual hours (which already include their descendants)
        Map<Id, List<Work_Item__c>> childrenByParentIds = new Map<Id, List<Work_Item__c>>();

        for (Work_Item__c workItem : workItemsQueried) {
            // Start with direct logged hours
            Decimal newActualHours = workItem.Total_Logged_Hours__c ?? 0;

            // Add children's actual hours
            if (childrenByParentIds.containsKey(workItem.Id)) {
                for (Work_Item__c child : childrenByParentIds.get(workItem.Id)) {
                    // Use the already-calculated child hours directly
                    // child is already the same object reference from allWorkItems
                    newActualHours += child.Actual_Hours__c ?? 0;
                }
            }

            // If the hours have changed, update the record in memory and register with UOW
            if (workItem.Actual_Hours__c != newActualHours) {
                workItem.Actual_Hours__c = newActualHours;
                // Update in the map to ensure subsequent reads get the updated value
                this.uow.registerDirty(workItem);
            }
        }

        // Commit all changes
        this.uow.commitWork();

        // Calculate and UPDATE actual hours for each work item (do the update here, not in Flow)
        Set<Id> parentIdsToUpdate = new Set<Id>();

        for (Work_Item__c workItem : workItemsToProcess) {
            // Start with direct logged hours (from time entries on this work item)
            workItem.Actual_Hours__c = workItem.Total_Logged_Hours__c ?? 0;

            // Add children's actual hours (which include their entire subtree)
            if (childrenByParentIds.containsKey(workItem.Id)) {
                for (Work_Item__c child : childrenByParentIds.get(workItem.Id)) {
                    workItem.Actual_Hours__c += child.Actual_Hours__c ?? 0;
                }
            }

            // Update the work item's actual hours
            this.uow.registerDirty(workItem);
        }

        // Commit the current work items' updates FIRST
        this.uow.commitWork();

        // Now update all ancestors recursively (they will query the committed child data)
        this.calculateActualHours(parentIdsToUpdate);
    }
}

