@IsTest
static void testIsAtRisk() {
    // Test overdue item
    Boolean atRisk = WorkItemService.isAtRisk(Date.today().addDays(-1), 50);
    System.assertEquals(true, atRisk, 'Overdue item should be at risk');

    // Test item due soon with low progress
    atRisk = WorkItemService.isAtRisk(Date.today().addDays(2), 50);
    System.assertEquals(true, atRisk, 'Item due within 3 days with <75% progress should be at risk');

    // Test item due soon with high progress
    atRisk = WorkItemService.isAtRisk(Date.today().addDays(2), 80);
    System.assertEquals(false, atRisk, 'Item due within 3 days with >=75% progress should not be at risk');

    // Test item not due soon
    atRisk = WorkItemService.isAtRisk(Date.today().addDays(10), 20);
    System.assertEquals(false, atRisk, 'Item due in >3 days should not be at risk');

    // Test null due date
    atRisk = WorkItemService.isAtRisk(null, 50);
    System.assertEquals(false, atRisk, 'Item with null due date should not be at risk');
}

