    @IsTest
    static void testWorkItemWrapperWithTimelineConflict() {
        // Create work item template with timeline validation
        Work_Item_Template__c templateWithValidation = new Work_Item_Template__c(
            Name = 'Timeline Validated Template',
            Description__c = 'Template with timeline validation',
            Timeline_Validation__c = 'Warning'
        );
        insert as user templateWithValidation;

        Project__c project = [SELECT Id FROM Project__c LIMIT 1];

        // Create parent work item
        Work_Item__c parent = new Work_Item__c(
            Work_Item_Name__c = 'Parent Item',
            Project__c = project.Id,
            Work_Item_Template__c = templateWithValidation.Id,
            Status__c = 'In Progress',
            Start_Date__c = Date.today(),
            Due_Date__c = Date.today().addDays(10)
        );
        insert as user parent;

        // Create child work item with dates outside parent range
        Work_Item__c child = new Work_Item__c(
            Work_Item_Name__c = 'Child Item',
            Project__c = project.Id,
            Work_Item_Template__c = templateWithValidation.Id,
            Parent_Work_Item__c = parent.Id,
            Status__c = 'Not Started',
            Start_Date__c = Date.today().addDays(-5), // Starts before parent
            Due_Date__c = Date.today().addDays(15) // Ends after parent
        );
        insert as user child;

        Test.startTest();
        WorkItemController.WorkItemWrapper result = WorkItemController.getWorkItemWithChildren(child.Id, 0);
        Test.stopTest();

        // Verify timeline conflict detected
        System.assertEquals(true, result.hasTimelineConflict, 'Should detect timeline conflict');
        System.assertNotEquals(null, result.timelineConflictMessage, 'Should have conflict message');
