    @IsTest
    static void testReorderWorkItems() {
        Project__c project = [SELECT Id FROM Project__c LIMIT 1];
        List<Work_Item__c> rootItems = [
            SELECT Id, Order__c
            FROM Work_Item__c
            WHERE Parent_Work_Item__c = NULL
            ORDER BY CreatedDate ASC
        ];

        System.assert(rootItems.size() >= 2, 'Should have at least 2 root items for reordering');

