        System.assertEquals(true, result.isAtRisk, 'Should be at risk');
        System.assertEquals(true, result.isBlocked, 'Should be blocked');
        System.assertEquals('Resource shortage', result.atRiskDetails, 'At risk details should match');
        System.assertEquals('Waiting for blocker', result.blockedDetails, 'Blocked details should match');
        System.assertEquals(blocker.Id, result.blockerWorkItemId, 'Blocker ID should match');
        System.assertNotEquals(null, result.blockerWorkItemName, 'Blocker name should be populated');
        System.assert(result.highlights.contains('at-risk'), 'Should include at-risk highlight');
        System.assert(result.highlights.contains('blocked'), 'Should include blocked highlight');
    }

