    @IsTest
    static void testReparentWorkItemBetweenParents() {
        // Get the first milestone and its children
        Work_Item__c milestone1 = [SELECT Id, Work_Item_Template__c FROM Work_Item__c WHERE Work_Item_Name__c = 'Milestone 0' LIMIT 1];
        Work_Item__c milestone2 = [SELECT Id, Work_Item_Template__c FROM Work_Item__c WHERE Work_Item_Name__c = 'Milestone 1' LIMIT 1];

        List<Work_Item__c> deliverables1 = [
            SELECT Id, Parent_Work_Item__c, Work_Item_Name__c, Work_Item_Template__c
            FROM Work_Item__c
            WHERE Parent_Work_Item__c = :milestone1.Id
            ORDER BY Work_Item_Name__c
        ];
        List<Work_Item__c> deliverables2 = [
            SELECT Id, Parent_Work_Item__c
            FROM Work_Item__c
            WHERE Parent_Work_Item__c = :milestone2.Id
            ORDER BY Work_Item_Name__c
        ];

        System.assertEquals(2, deliverables1.size(), 'Milestone 1 should have 2 deliverables');
        System.assertEquals(2, deliverables2.size(), 'Milestone 2 should have 2 deliverables');

        // Create Allowed_Child_Type__c to allow deliverable under milestone
        Allowed_Child_Type__c allowedChild = new Allowed_Child_Type__c(
            Parent_Work_Item_Template__c = milestone1.Work_Item_Template__c,
            Child_Work_Item_Template__c = deliverables1[0].Work_Item_Template__c
        );
        insert as user allowedChild;

        Test.startTest();
        // Move first deliverable from milestone1 to milestone2 (make it sibling of milestone2's first deliverable)
        WorkItemController.moveWorkItem(deliverables1[0].Id, deliverables2[0].Id, milestone2.Id);
        Test.stopTest();

        // Verify the deliverable was moved
        Work_Item__c movedDeliverable = [
            SELECT Id, Parent_Work_Item__c
            FROM Work_Item__c
            WHERE Id = :deliverables1[0].Id
        ];

        System.assertEquals(milestone2.Id, movedDeliverable.Parent_Work_Item__c, 'Deliverable should be reparented to Milestone 2');

        // Verify counts
        Integer count1 = [SELECT COUNT() FROM Work_Item__c WHERE Parent_Work_Item__c = :milestone1.Id];
        Integer count2 = [SELECT COUNT() FROM Work_Item__c WHERE Parent_Work_Item__c = :milestone2.Id];

        System.assertEquals(1, count1, 'Milestone 1 should now have 1 deliverable');
        System.assertEquals(3, count2, 'Milestone 2 should now have 3 deliverables');
    }

