        Allowed_Child_Type__c allowedChild = new Allowed_Child_Type__c(
            Parent_Work_Item_Template__c = milestone1.Work_Item_Template__c,
            Child_Work_Item_Template__c = deliverables1[0].Work_Item_Template__c
        );
        insert as user allowedChild;

        Test.startTest();
        // Drop deliverable from milestone1 onto a deliverable of milestone2
        // This should make it a sibling of that deliverable (child of milestone2)
        WorkItemController.moveWorkItem(deliverables1[0].Id, deliverables2[0].Id, milestone2.Id);
        Test.stopTest();

        // Verify the deliverable was moved
        Work_Item__c movedDeliverable = [
            SELECT Id, Parent_Work_Item__c
            FROM Work_Item__c
            WHERE Id = :deliverables1[0].Id
        ];

        System.assertEquals(milestone2.Id, movedDeliverable.Parent_Work_Item__c, 'Deliverable should be reparented to Milestone 2 (same template, should work)');
    }

    @IsTest
    static void testReparentWorkItemNotAllowed() {
        // Get two milestones
        Work_Item__c milestone1 = [SELECT Id FROM Work_Item__c WHERE Work_Item_Name__c = 'Milestone 0' LIMIT 1];
        Work_Item__c milestone2 = [SELECT Id FROM Work_Item__c WHERE Work_Item_Name__c = 'Milestone 1' LIMIT 1];

        List<Work_Item__c> deliverables1 = [
            SELECT Id, Parent_Work_Item__c
            FROM Work_Item__c
            WHERE Parent_Work_Item__c = :milestone1.Id
            ORDER BY Work_Item_Name__c
        ];
        List<Work_Item__c> deliverables2 = [
            SELECT Id, Parent_Work_Item__c
            FROM Work_Item__c
            WHERE Parent_Work_Item__c = :milestone2.Id
            ORDER BY Work_Item_Name__c
        ];

        // DO NOT create Allowed_Child_Type__c - should fail

        Test.startTest();
        Boolean exceptionThrown = false;
        try {
            WorkItemController.moveWorkItem(deliverables1[0].Id, deliverables2[0].Id, milestone2.Id);
        } catch (AppException e) {
            exceptionThrown = true;
            System.assert(e.getMessage().contains('does not allow this work item type'), 'Should throw error about not allowing child type');
        }
        Test.stopTest();

        System.assertEquals(true, exceptionThrown, 'Should throw exception when parent does not allow child type');
    }

    @IsTest
    static void testReparentWorkItemDirectlyOntoParent() {
        // Get two milestones
        Work_Item__c milestone1 = [SELECT Id, Work_Item_Template__c FROM Work_Item__c WHERE Work_Item_Name__c = 'Milestone 0' LIMIT 1];
        Work_Item__c milestone2 = [SELECT Id, Work_Item_Template__c, Parent_Work_Item__c FROM Work_Item__c WHERE Work_Item_Name__c = 'Milestone 1' LIMIT 1];

        List<Work_Item__c> deliverables1 = [
            SELECT Id, Parent_Work_Item__c, Work_Item_Template__c
            FROM Work_Item__c
            WHERE Parent_Work_Item__c = :milestone1.Id
            ORDER BY Work_Item_Name__c
        ];

        Work_Item__c deliverable = deliverables1[0];

        // Create Allowed_Child_Type__c to allow deliverable under milestone
        Allowed_Child_Type__c allowedChild = new Allowed_Child_Type__c(
            Parent_Work_Item_Template__c = milestone2.Work_Item_Template__c,
            Child_Work_Item_Template__c = deliverable.Work_Item_Template__c
        );
        insert as user allowedChild;

        Test.startTest();
        // Drop deliverable directly onto milestone2
        // Use milestone2's parent to match how LWC sends the data (makes dragged item sibling of target)
        WorkItemController.moveWorkItem(deliverable.Id, milestone2.Id, deliverable.Parent_Work_Item__c);
        Test.stopTest();

        // Verify the deliverable was moved
        Work_Item__c movedDeliverable = [
            SELECT Id, Parent_Work_Item__c
            FROM Work_Item__c
            WHERE Id = :deliverable.Id
        ];

        System.assertEquals(milestone2.Id, movedDeliverable.Parent_Work_Item__c, 'Deliverable should be reparented to Milestone 2');

        // Verify counts
        Integer count1 = [SELECT COUNT() FROM Work_Item__c WHERE Parent_Work_Item__c = :milestone1.Id];
        Integer count2 = [SELECT COUNT() FROM Work_Item__c WHERE Parent_Work_Item__c = :milestone2.Id];

        System.assertEquals(1, count1, 'Milestone 1 should now have 1 deliverable');
        System.assertEquals(3, count2, 'Milestone 2 should now have 3 deliverables');
    }
}

